INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('c437b8c0-d48b-48d9-b975-fce1bc0c3740', NULL, 'system', 'notifications.update', 'notifications', '055f3926-0ff5-49f6-a0ed-133d9a3c0c68', '{"subject":"We received your order {{order_number}}","template":"Hi {{customer_name}}, thanks for your order {{order_number}} ({{total}}). We will confirm it shortly. - {{store_name}}"}', '{"subject":"Order {{ order.name }} received","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Thank you for your order!</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Thank you for your order!</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, we have received your order {{ order.name }}. We will call you shortly to confirm it before it ships.</p>\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">View your order</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('b4f37316-d880-48b3-bacb-d402407d126b', NULL, 'system', 'notifications.update', 'notifications', '21a5c317-e9f0-4c06-aa82-484f2a320c2c', '{"subject":"Order {{order_number}} confirmed","template":"Your order {{order_number}} is confirmed and being prepared. Total due on delivery: {{cod_amount}}. - {{store_name}}"}', '{"subject":"Order {{ order.name }} confirmed","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order is confirmed</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order is confirmed</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your order {{ order.name }} is confirmed and we are getting it ready.</p>\n{% if order.cod_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Please keep <strong>{{ order.cod_amount | money }}</strong> ready to pay on delivery.</p>{% endif %}\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">View your order</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('fe643d4b-8289-4ee4-b274-4cddefb9e556', NULL, 'system', 'notifications.update', 'notifications', '02b0fbc8-de29-4003-9687-4bc4ea1c1695', '{"subject":"Advance payment needed for {{order_number}}","template":"To confirm order {{order_number}}, please pay an advance of {{advance_amount}}. Pay here: {{track_order_url}} - {{store_name}}"}', '{"subject":"Advance payment needed for order {{ order.name }}","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>One more step to confirm your order</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">One more step to confirm your order</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, to confirm order {{ order.name }} please pay an advance of <strong>{{ order.advance_amount | money }}</strong>. The rest is paid on delivery.</p>\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">Pay the advance</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('a6ea61e5-75bb-45fe-b4b0-942b27bf08f7', NULL, 'system', 'notifications.update', 'notifications', '87a883a7-f8a3-43f9-b4e7-3a84d11209a9', '{"template":"Your order {{order_number}} has been handed to {{courier_name}}. Tracking: {{tracking_number}} {{tracking_url}} - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your order {{order_number}} has been handed to {{courier_name}}. Tracking number: {{tracking_number}}. Track it here: {{tracking_url}} anytime.\n\nThe {{store_name}} team"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('1475454f-7899-4aa8-b1af-8fb99eef674b', NULL, 'system', 'notifications.update', 'notifications', '4d44b392-9d34-4cbf-a951-c4db25988659', '{"subject":"Order {{order_number}} is on the way","template":"Your order {{order_number}} has been handed to {{courier_name}}. Tracking: {{tracking_number}} {{tracking_url}} - {{store_name}}"}', '{"subject":"Order {{ order.name }} is on the way","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order is on the way</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order is on the way</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your order {{ order.name }} has been handed to {{ shipment.courier | default: \"the courier\" }}.</p>\n{% if shipment.tracking_number %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Tracking number: <strong>{{ shipment.tracking_number }}</strong></p>{% endif %}\n{% if order.cod_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Please keep <strong>{{ order.cod_amount | money }}</strong> ready to pay on delivery.</p>{% endif %}\n</td></tr>\n{% if shipment.tracking_url or order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ shipment.tracking_url | default: order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">Track your parcel</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Order</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.name }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Items</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.item_count }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Total</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.total_price | money }}</td></tr>\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">To pay on delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.cod_amount | money }}</td></tr>{% endif %}\n</table>\n</td></tr>\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('5cff845d-b07f-4807-aa97-547a0339191f', NULL, 'system', 'notifications.update', 'notifications', 'b3123a67-6e6a-4ca0-adbb-71363dc54276', '{"subject":"Order {{order_number}} delivered","template":"Your order {{order_number}} was delivered. We hope you love it! - {{store_name}}"}', '{"subject":"Order {{ order.name }} delivered","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order was delivered</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order was delivered</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your order {{ order.name }} was delivered. We hope you love it!</p>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">If anything is not right, just reply to this email{% if shop.phone %} or call us at {{ shop.phone }}{% endif %}.</p>\n</td></tr>\n\n<tr><td style=\"padding:8px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Order</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.name }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Items</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.item_count }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Total</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.total_price | money }}</td></tr>\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">To pay on delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.cod_amount | money }}</td></tr>{% endif %}\n</table>\n</td></tr>\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('f178ec7f-1b2b-4ce7-904e-6b760e440fd2', NULL, 'system', 'notifications.update', 'notifications', 'a758f9ef-e845-453a-af73-9f122f4e3dd5', '{"subject":"Order {{order_number}} cancelled","template":"Your order {{order_number}} has been cancelled. Questions? Call {{store_phone}}. - {{store_name}}"}', '{"subject":"Order {{ order.name }} cancelled","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order was cancelled</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order was cancelled</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your order {{ order.name }} has been cancelled.</p>\n{% if order.paid_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">You paid {{ order.paid_amount | money }} for this order. We will contact you about the refund.</p>{% endif %}\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Questions? Reply to this email{% if shop.phone %} or call us at {{ shop.phone }}{% endif %}.</p>\n</td></tr>\n\n<tr><td style=\"padding:8px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Order</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.name }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Items</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.item_count }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Total</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.total_price | money }}</td></tr>\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">To pay on delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.cod_amount | money }}</td></tr>{% endif %}\n</table>\n</td></tr>\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('cfae7fb4-4ffa-4814-85f0-6a67eae6cb07', NULL, 'system', 'notifications.update', 'notifications', 'd4f6e725-9ad1-4a5f-9a50-9cab8b00b3a4', '{"subject":"Return received for {{order_number}}","template":"We have received the return for order {{order_number}}. - {{store_name}}"}', '{"subject":"Return received for order {{ order.name }}","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>We received your return</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">We received your return</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, the returned parcel for order {{ order.name }} has reached us.</p>\n{% if order.paid_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">We will contact you about your payment of {{ order.paid_amount | money }}.</p>{% endif %}\n</td></tr>\n\n\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('6f5b5427-2854-4fa1-a2d0-ada597f1b276', NULL, 'system', 'notifications.update', 'notifications', '3b0ab221-a9ea-4676-8297-0cf233eb5637', '{"subject":"Pre-order {{order_number}} confirmed","template":"Your pre-order {{order_number}} is confirmed. We will ship it as soon as it arrives in stock. - {{store_name}}"}', '{"subject":"Pre-order {{ order.name }} confirmed","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your pre-order is confirmed</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your pre-order is confirmed</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your pre-order {{ order.name }} is confirmed. We will ship it as soon as it arrives in stock.</p>\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">View your order</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('89088755-ba8f-4489-bfbf-b50454806a44', NULL, 'system', 'notifications.update', 'notifications', '71a15d13-4a87-4220-8ac7-583966b3e58e', '{"template":"Your order {{order_number}} was delivered. We hope you love it! - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your order {{order_number}} was delivered. We hope you love it! Reply here if anything is not right.\n\nThe {{store_name}} team"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('140489d3-1ae1-4ac4-b190-65082814be1c', NULL, 'system', 'notifications.update', 'notifications', '3d902377-b301-4fcd-bf75-6ff56fff9a8f', '{"template":"Your order {{order_number}} has been cancelled. Questions? Call {{store_phone}}. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your order {{order_number}} has been cancelled. Questions? Call us at {{store_phone}} or reply here.\n\nThe {{store_name}} team"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('84dc3ce7-01ed-4805-8246-4121673e840a', NULL, 'system', 'notifications.update', 'notifications', '9d8952c1-ca18-49f8-876a-a9b188eb784c', '{"subject":"Order {{order_number}} is out for delivery","template":"Your order {{order_number}} is out for delivery today. Please keep {{cod_amount}} ready. - {{store_name}}"}', '{"subject":"Order {{ order.name }} is out for delivery","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order arrives today</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order arrives today</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your order {{ order.name }} is out for delivery today{% if shipment.courier %} with {{ shipment.courier }}{% endif %}.</p>\n{% if order.cod_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Please keep <strong>{{ order.cod_amount | money }}</strong> ready for the delivery person.</p>{% endif %}\n</td></tr>\n{% if shipment.tracking_url or order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ shipment.tracking_url | default: order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">Track your parcel</a>\n</td></tr>{% endif %}\n\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('7c9bd1f7-2081-4dd7-afc0-0c71ede5b42b', NULL, 'system', 'notifications.update', 'notifications', '61c86a55-c948-40c4-8d42-08175541b9e7', '{"subject":"Order {{order_number}} is being returned","template":"Your order {{order_number}} is being returned to us. Questions? Call {{store_phone}}. - {{store_name}}"}', '{"subject":"Order {{ order.name }} is being returned","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order is being returned</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order is being returned</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, the parcel for order {{ order.name }} is on its way back to us.</p>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Questions? Reply to this email{% if shop.phone %} or call us at {{ shop.phone }}{% endif %}.</p>\n</td></tr>\n\n\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('18f06e93-b807-41b1-99e7-c6dc2fab8c65', NULL, 'system', 'notifications.update', 'notifications', 'd120141f-a603-475b-9d6f-e6d91b667bd9', '{"subject":"Payment for {{order_number}} did not go through","template":"Your payment of {{payment_amount}} for order {{order_number}} did not go through. Try again: {{track_order_url}} - {{store_name}}"}', '{"subject":"Payment for order {{ order.name }} did not go through","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your payment didn''t go through</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your payment didn''t go through</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your payment of <strong>{{ payment.amount | money }}</strong> for order {{ order.name }} did not go through. No money was taken. You can try again below.</p>\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">Try again</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Order</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.name }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Items</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.item_count }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Total</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.total_price | money }}</td></tr>\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">To pay on delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.cod_amount | money }}</td></tr>{% endif %}\n</table>\n</td></tr>\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('b0c8643e-920a-4577-85c1-4919d23257dc', NULL, 'system', 'notifications.update', 'notifications', 'edaccef4-e3e0-4440-9feb-b5230eeb0ae6', '{"subject":"Payment received for {{order_number}}","template":"We received {{payment_amount}} for order {{order_number}}. Thank you! - {{store_name}}"}', '{"subject":"Payment received for order {{ order.name }}","template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>We received your payment</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">We received your payment</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, we received <strong>{{ payment.amount | money }}</strong> for order {{ order.name }}. Thank you!</p>\n{% if order.due_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Still to pay on delivery: <strong>{{ order.due_amount | money }}</strong>.</p>{% endif %}\n</td></tr>\n\n<tr><td style=\"padding:8px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Order</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.name }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Items</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.item_count }}</td></tr>\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Total</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.total_price | money }}</td></tr>\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">To pay on delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.cod_amount | money }}</td></tr>{% endif %}\n</table>\n</td></tr>\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('bee57859-22f7-48c1-bb33-e43881c34af2', NULL, 'system', 'notifications.update', 'notifications', '85597e4c-ef8b-4898-a4bb-0dfd56f4630e', '{"template":"Hi {{customer_name}}, thanks for your order {{order_number}} ({{total}}). We will confirm it shortly. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, thank you for your order {{order_number}} of {{total}}. We will call you shortly to confirm it.\n\nThank you for shopping with {{store_name}} today."}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('5b91cd9d-5055-46bf-b195-f1bc1021a6bb', NULL, 'system', 'notifications.update', 'notifications', 'f179e123-de3a-4293-8ba8-ff1b2d949112', '{"template":"Your order {{order_number}} is confirmed and being prepared. Total due on delivery: {{cod_amount}}. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your order {{order_number}} is confirmed and we are getting it ready. Amount to pay on delivery: {{cod_amount}}.\n\nThank you, the {{store_name}} team"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('e0c3d1ab-73c4-41e4-a501-2c8d09a76f87', NULL, 'system', 'notifications.update', 'notifications', '8c25ee01-5980-4dc1-b6ca-6e9a04e2eae9', '{"template":"To confirm order {{order_number}}, please pay an advance of {{advance_amount}}. Pay here: {{track_order_url}} - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, to confirm order {{order_number}} please pay an advance of {{advance_amount}} here: {{track_order_url}} and we will ship it right away.\n\nThank you, the {{store_name}} team"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('cf770af0-a5cc-4fce-baa0-42a74c89844c', NULL, 'system', 'notifications.update', 'notifications', '865613a0-250f-4e57-b07e-354b5e53b507', '{"template":"We have received the return for order {{order_number}}. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, the returned parcel for order {{order_number}} has reached us. We will be in touch soon.\n\nThe {{store_name}} team"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('df76a9a3-fafa-473b-9ca4-de7e260d11dd', NULL, 'system', 'notifications.update', 'notifications', 'ed990430-ccba-4426-97f9-03dde24098aa', '{"template":"Your pre-order {{order_number}} is confirmed. We will ship it as soon as it arrives in stock. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your pre-order {{order_number}} is confirmed. We will ship it as soon as it arrives in stock.\n\nThank you, the {{store_name}} team"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('6cb731f2-759a-486a-bace-319530e3249c', NULL, 'system', 'notifications.update', 'notifications', 'e157af2e-73a3-4589-8c29-40897ca3d2eb', '{"template":"Your order {{order_number}} is out for delivery today. Please keep {{cod_amount}} ready. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your order {{order_number}} is out for delivery today. Please keep {{cod_amount}} ready for the delivery person.\n\nThe {{store_name}} team"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('193c73fb-97c3-4ad1-b122-a67426795449', NULL, 'system', 'notifications.update', 'notifications', 'b670b3fe-b17e-4689-8370-bda7b8f56ae2', '{"template":"Your order {{order_number}} is being returned to us. Questions? Call {{store_phone}}. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, the parcel for order {{order_number}} is on its way back to us. Questions? Call us at {{store_phone}} or reply here.\n\nThe {{store_name}} team"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('fbc83090-4e1b-4a0f-a73a-7cd64859e778', NULL, 'system', 'notifications.update', 'notifications', '1fe5aa52-d712-4f3b-9264-4762cd809100', '{"template":"Your payment of {{payment_amount}} for order {{order_number}} did not go through. Try again: {{track_order_url}} - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your payment of {{payment_amount}} for order {{order_number}} did not go through. You can try again here: {{track_order_url}} at any time.\n\nThe {{store_name}} team"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('9acf99c5-605d-44b6-8999-60101b58512a', NULL, 'system', 'notifications.update', 'notifications', 'd3778baa-5bd6-4bf1-8b4f-d247a0886234', '{"template":"We received {{payment_amount}} for order {{order_number}}. Thank you! - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, we received your payment of {{payment_amount}} for order {{order_number}}. Thank you!\n\nThe {{store_name}} team"}', '{}', '2026-10-30T08:17:02.731Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('bcb5e5af-d9d5-4994-89dd-3f19302c1268', NULL, 'system', 'notifications.update', 'notifications', '055f3926-0ff5-49f6-a0ed-133d9a3c0c68', '{"template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Thank you for your order!</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Thank you for your order!</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, we have received your order {{ order.name }}. We will call you shortly to confirm it before it ships.</p>\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">View your order</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{"template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Thank you for your order!</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">{% if order.name %}Order {{ order.name }}{% endif %}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Thank you for your order!</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, we have received your order {{ order.name }}.{% if order.reply_url %} Please confirm it below so we can send it quickly.{% else %} We will call you shortly to confirm it before it ships.{% endif %}</p>\n</td></tr>\n{% if order.reply_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.reply_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">Confirm your order</a>\n<p style=\"margin:12px 0 0;font-size:13px;line-height:1.6;color:#6b7280;\">Can''t take this order? <a href=\"{{ order.reply_url }}?action=cancel\" style=\"color:#6b7280;\">Cancel it here</a></p>\n</td></tr>{% else %}{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">View your order</a>\n</td></tr>{% endif %}{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>"}', '{}', '2026-10-30T08:17:02.761Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('c94bb05c-8813-4ab4-8fcc-74986623d7c2', NULL, 'system', 'notifications.update', 'notifications', '21a5c317-e9f0-4c06-aa82-484f2a320c2c', '{"template":"{% assign accent = shop.accent_color | default: \"#111827\" %}<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Your order is confirmed</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f5f7;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f5f7;\">\n<tr><td align=\"center\" style=\"padding:32px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;\">\n<tr><td style=\"padding:28px 32px 0;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n<td>{% if shop.logo_url %}<img src=\"{{ shop.logo_url }}\" alt=\"{{ shop.name }}\" height=\"36\" style=\"display:block;height:36px;max-width:180px;border:0;\">{% else %}<span style=\"font-size:20px;font-weight:700;color:#111827;\">{{ shop.name }}</span>{% endif %}</td>\n<td align=\"right\" style=\"font-size:13px;color:#6b7280;\">Order {{ order.name }}</td>\n</tr></table>\n</td></tr>\n<tr><td style=\"padding:24px 32px 4px;\">\n<h1 style=\"margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;\">Your order is confirmed</h1>\n<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Hi {{ customer.first_name | default: \"there\" }}, your order {{ order.name }} is confirmed and we are getting it ready.</p>\n{% if order.cod_amount > 0 %}<p style=\"margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;\">Please keep <strong>{{ order.cod_amount | money }}</strong> ready to pay on delivery.</p>{% endif %}\n</td></tr>\n{% if order.status_url %}<tr><td style=\"padding:12px 32px 4px;\">\n<a href=\"{{ order.status_url }}\" style=\"display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;\">View your order</a>\n</td></tr>{% endif %}\n<tr><td style=\"padding:8px 32px 0;\">\n<p style=\"margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Order summary</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-top:1px solid #e5e7eb;\">\n{% for item in order.line_items %}<tr>\n<td width=\"56\" style=\"padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;\">{% if item.image_url %}<img src=\"{{ item.image_url }}\" alt=\"\" width=\"48\" height=\"48\" style=\"display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;\">{% endif %}</td>\n<td style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;\">{{ item.title }}{% if item.variant_title %}<br><span style=\"color:#6b7280;font-size:13px;\">{{ item.variant_title }}</span>{% endif %}<br><span style=\"color:#6b7280;font-size:13px;\">Qty {{ item.quantity }}</span></td>\n<td align=\"right\" style=\"padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;\">{{ item.line_price | money }}</td>\n</tr>{% endfor %}\n</table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top:8px;\">\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Subtotal</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.subtotal_price | money }}</td></tr>\n{% if order.discount_price > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Discount</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">-{{ order.discount_price | money }}</td></tr>{% endif %}\n<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Delivery</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.delivery_price | money }}</td></tr>\n<tr><td style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">Total</td><td align=\"right\" style=\"padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;\">{{ order.total_price | money }}</td></tr>\n{% if order.paid_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\">Paid</td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\">{{ order.paid_amount | money }}</td></tr>{% endif %}\n{% if order.cod_amount > 0 %}<tr><td style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>To pay on delivery</strong></td><td align=\"right\" style=\"padding:6px 0;font-size:14px;color:#374151;\"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}\n</table>\n</td></tr>\n{% if order.shipping_address.address %}<tr><td style=\"padding:20px 32px 0;\">\n<p style=\"margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;\">Delivery address</p>\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>\n</td></tr>{% endif %}\n<tr><td style=\"padding:28px 32px 28px;\">\n<p style=\"margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;\">{{ shop.name }}{%